import { env } from 'node:process'
import { expect, test } from '@playwright/test'
import AxeBuilder from '@axe-core/playwright'
import {
  dueFirst, dueRelease, finalNegative, finalPaid, hugeAmounts, reserveHeld, salesOpen, zeroSales,
} from '../src/demo/fixtures/payoutStatements.js'

// Organizer payout statement and admin Due view against API responses
// generated by the real statement and schedule services (see the fixtures
// file). Set PAYOUT_QA_SCREENSHOTS=<dir> to save review screenshots.
const shots = env.PAYOUT_QA_SCREENSHOTS
const json = (route, data, status = 200) => route.fulfill({ status, contentType: 'application/json', body: JSON.stringify(data) })

async function base(page) {
  await page.emulateMedia({ reducedMotion: 'reduce' })
  await page.route('**/api/v1/**', route => json(route, {}))
  await page.route('**/api/v1/health', route => json(route, { status: 'ok' }))
  await page.route('**/api/v1/config', route => json(route, { launch_capabilities: {}, payment_mode: 'simulate',
    service_fee_percent: '5.0', service_fee_flat_cents: 100, organizer_payout_terms: null }))
}
async function statementAt(page, statement) {
  await page.route('**/api/v1/organizer/events/12/finance/payout_statement**', route => json(route, statement))
  await page.goto('/dashboard/events/12/statement')
  await expect(page.getByTestId('statement-status')).toHaveText(statement.status_label)
}
async function checkLayout(page, width) {
  const result = await new AxeBuilder({ page }).include('#payout-statement, main').analyze()
  expect(result.violations.filter(item => ['serious', 'critical'].includes(item.impact))).toEqual([])
  expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBeLessThanOrEqual(width)
}
const snap = (page, name) => shots ? page.screenshot({ path: `${shots}/${name}.png`, fullPage: true, scale: 'css' }) : null

for (const width of [390, 1280]) {
  test.describe(`at ${width}px`, () => {
    test.beforeEach(async ({ page }) => { await page.setViewportSize({ width, height: 900 }); await base(page) })

    test('paid with reserve held: every line, the transfer and no full account number', async ({ page }) => {
      await statementAt(page, reserveHeld)
      await expect(page.getByText('Bank transfer to account ending 4321')).toBeVisible()
      await expect(page.getByText(/Ref TRF-20270201-07/)).toBeVisible()
      await expect(page.getByText('You already have this cash, so it is not part of the bank transfer.')).toBeVisible()
      await expect(page.getByTestId('balance-remaining')).toContainText('$0.00')
      await checkLayout(page, width)
      await snap(page, `statement-reserve-held-${width}`)
    })

    test('final, negative balance, zero sales, sales open and worst-case names and amounts', async ({ page }) => {
      await statementAt(page, finalNegative)
      await expect(page.getByText('This event is closed. You owe $62.16, which comes out of your next payout.')).toBeVisible()
      await checkLayout(page, width)
      if (width === 390) await snap(page, 'statement-final-negative-390')
      await page.unroute('**/api/v1/organizer/events/12/finance/payout_statement**')
      await statementAt(page, hugeAmounts)
      await expect(page.getByText('$1,000,000.00').first()).toBeVisible()
      await checkLayout(page, width)
      if (width === 390) await snap(page, 'statement-worst-case-390')
      for (const statement of [finalPaid, zeroSales, salesOpen]) {
        await page.unroute('**/api/v1/organizer/events/12/finance/payout_statement**')
        await statementAt(page, statement)
        await checkLayout(page, width)
      }
      if (width === 1280) {
        await page.unroute('**/api/v1/organizer/events/12/finance/payout_statement**')
        await statementAt(page, finalPaid)
        await snap(page, 'statement-final-1280')
      }
    })

    test('admin Due view lists transfers and reserves with their next step', async ({ page }) => {
      let due = dueFirst
      await page.route('**/api/v1/admin/payout_schedule**', route => json(route, due))
      await page.goto('/admin/payouts?view=due')
      const row = page.getByTestId(`due-row-${dueFirst.transfers[0].event.id}`)
      await expect(row).toContainText('Due by Feb 3, 2027')
      await expect(row.getByRole('button', { name: /Hold \$894\.51 reserve/ })).toBeVisible()
      expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBeLessThanOrEqual(width)
      due = dueRelease
      await page.reload()
      await expect(page.getByText('1 overdue')).toBeVisible()
      await expect(page.getByTestId(`due-row-${dueRelease.reserves[0].event.id}`)).toContainText('Release the reserve')
      const result = await new AxeBuilder({ page }).analyze()
      expect(result.violations.filter(item => ['serious', 'critical'].includes(item.impact))).toEqual([])
      expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBeLessThanOrEqual(width)
      await snap(page, `admin-due-${width}`)
    })
  })
}

test('prints a clean statement without navigation or buttons', async ({ page }) => {
  await page.setViewportSize({ width: 1280, height: 900 }); await base(page)
  await statementAt(page, reserveHeld)
  await page.emulateMedia({ media: 'print' })
  await expect(page.getByRole('button', { name: 'Print' })).toBeHidden()
  await expect(page.getByRole('link', { name: 'Back to event finances' })).toBeHidden()
  for (const nav of await page.locator('.app-nav').all()) await expect(nav).toBeHidden()
  await expect(page.getByText('How your payout adds up')).toBeVisible()
  await snap(page, 'statement-print-1280')
})
